/* Claymorphism — puffy pastel clay blobs, chunky radii, inner highlights */
.theme-claymorphism {
  --bg: oklch(0.95 0.035 300);
  --surface: oklch(0.99 0.02 300);
  --surface-2: oklch(0.93 0.05 290);
  --fg: oklch(0.34 0.06 300);
  --fg-muted: oklch(0.56 0.05 300);
  --accent: oklch(0.72 0.16 340);
  --accent-fg: oklch(0.99 0.01 340);
  --accent-2: oklch(0.78 0.14 210);
  --line: oklch(0.86 0.05 300);
  --success: oklch(0.78 0.14 160);
  --warning: oklch(0.85 0.14 85);
  --danger: oklch(0.68 0.18 20);

  --radius: 2rem;
  --radius-sm: 1.25rem;
  --radius-lg: 2.75rem;
  --radius-pill: 9999px;

  --shadow-1: 0 8px 16px -6px oklch(0.6 0.1 300 / 40%), inset 0 -4px 8px oklch(0.7 0.1 300 / 25%),
    inset 0 4px 8px oklch(1 0 0 / 80%);
  --shadow-2: 0 16px 30px -10px oklch(0.6 0.1 300 / 45%), inset 0 -6px 12px oklch(0.7 0.1 300 / 28%),
    inset 0 6px 12px oklch(1 0 0 / 85%);
  --shadow-3: 0 28px 54px -16px oklch(0.55 0.1 300 / 50%), inset 0 -8px 16px oklch(0.7 0.1 300 / 30%),
    inset 0 8px 16px oklch(1 0 0 / 85%);
  --glow: 0 0 0 6px oklch(0.72 0.16 340 / 18%);

  --border-width: 0px;
  --blur-amount: 0px;

  --font-display: "Fredoka", sans-serif;
  --font-body: "Fredoka", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.01em;
  --label-transform: none;
  --label-tracking: 0.02em;

  background-color: var(--bg);
  background-image:
    radial-gradient(40rem 30rem at 10% 0%, oklch(0.87 0.09 340 / 60%), transparent 60%),
    radial-gradient(40rem 30rem at 100% 30%, oklch(0.87 0.09 210 / 55%), transparent 60%);
  background-attachment: fixed;
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-claymorphism h1,
.theme-claymorphism h2,
.theme-claymorphism h3 {
  font-family: var(--font-display);
  font-weight: 800;
  letter-spacing: var(--tracking-display);
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
